INSERT INTO c10_demo.intent_guidance_v1(control_key,module_code,capability_key,content) VALUES('intent.approval_publish','intent',NULL,'{"title":{"en":"Validate, approve, publish","bn":"যাচাই, অনুমোদন, প্রকাশ"},"what":{"en":"Three separate steps. Only the tenant Owner can approve and publish.","bn":"তিনটি আলাদা ধাপ। শুধু টেন্যান্ট মালিক অনুমোদন ও প্রকাশ করতে পারেন।"},"why":{"en":"Keeps a deliberate, audited path from idea to setting.","bn":"ধারণা থেকে সেটিং পর্যন্ত সুচিন্তিত ও অডিটযোগ্য পথ বজায় রাখে।"},"when":{"en":"After a clean preview.","bn":"পরিষ্কার প্রিভিউয়ের পর।"},"default":{"en":"Business Owners may submit and preview but not publish.","bn":"ব্যবসার মালিক জমা ও প্রিভিউ করতে পারেন, প্রকাশ নয়।"},"exception":{"en":"A stale preview, a changed setting or a blocking conflict stops the step.","bn":"পুরোনো প্রিভিউ, বদলে যাওয়া সেটিং বা ব্লকিং দ্বন্দ্ব ধাপ থামায়।"},"consequence":{"en":"Publishing stores an advisory setting version. It does not post stock, money or permissions.","bn":"প্রকাশ করলে একটি পরামর্শমূলক সেটিং সংস্করণ সংরক্ষিত হয়। স্টক, টাকা বা অনুমতি পোস্ট হয় না।"},"data_formula_units":{"en":"Each publish creates a new immutable version with a hash.","bn":"প্রতিটি প্রকাশে হ্যাশসহ নতুন অপরিবর্তনীয় সংস্করণ তৈরি হয়।"},"linked_report":{"en":"History and audit panel.","bn":"ইতিহাস ও অডিট প্যানেল।"}}'::jsonb);
INSERT INTO c10_demo.intent_guidance_v1(control_key,module_code,capability_key,content) VALUES('intent.engineering_requirement','intent',NULL,'{"title":{"en":"Engineering requirement","bn":"ইঞ্জিনিয়ারিং রিকোয়ারমেন্ট"},"what":{"en":"A stored, structured ticket for something no certified handler can do yet.","bn":"যা এখনো কোনো সার্টিফাইড হ্যান্ডলার করতে পারে না, তার জন্য সংরক্ষিত কাঠামোবদ্ধ টিকিট।"},"why":{"en":"So the need is not lost and nothing pretends to work.","bn":"যাতে চাহিদা হারিয়ে না যায় এবং কিছু কাজ করার ভান না করে।"},"when":{"en":"Shown automatically for unsupported requests.","bn":"অসমর্থিত অনুরোধে স্বয়ংক্রিয়ভাবে দেখায়।"},"default":{"en":"Status NEEDS_HANDLER_BUILD (or NOT_ALLOWED_BY_POLICY for refused requests).","bn":"স্ট্যাটাস NEEDS_HANDLER_BUILD (প্রত্যাখ্যাত হলে NOT_ALLOWED_BY_POLICY)।"},"exception":{"en":"Policy-refused requests are never built through this path.","bn":"নীতিগতভাবে প্রত্যাখ্যাত অনুরোধ এই পথে কখনো তৈরি হয় না।"},"consequence":{"en":"Nothing executes. Engineers must build and certify a handler first.","bn":"কিছুই চলে না। আগে ইঞ্জিনিয়ারকে হ্যান্ডলার বানিয়ে সার্টিফাই করতে হবে।"},"data_formula_units":{"en":"Lists data entities and testable acceptance criteria.","bn":"ডেটা এন্টিটি ও পরীক্ষাযোগ্য গ্রহণযোগ্যতার শর্ত তালিকাভুক্ত।"},"linked_report":{"en":"Engineering requirements panel.","bn":"ইঞ্জিনিয়ারিং রিকোয়ারমেন্ট প্যানেল।"}}'::jsonb);
INSERT INTO c10_demo.intent_guidance_v1(control_key,module_code,capability_key,content) VALUES('intent.preview_diff','intent',NULL,'{"title":{"en":"Safe preview","bn":"নিরাপদ প্রিভিউ"},"what":{"en":"A dry run showing before/after values, a worked sample, the formula and what else is affected.","bn":"আগে/পরে মান, একটি নমুনা হিসাব, সূত্র এবং আর কী প্রভাবিত হবে তার ড্রাই-রান।"},"why":{"en":"You see the consequence before anything changes.","bn":"কিছু বদলানোর আগেই ফলাফল দেখতে পান।"},"when":{"en":"After interpreting and before approving.","bn":"ব্যাখ্যার পরে, অনুমোদনের আগে।"},"default":{"en":"Uses the capability''s built-in sample numbers; you can type your own.","bn":"সক্ষমতার নিজস্ব নমুনা সংখ্যা ব্যবহার হয়; নিজের সংখ্যাও দিতে পারেন।"},"exception":{"en":"Blocking conflicts (for example no effective change) stop validation.","bn":"ব্লকিং দ্বন্দ্ব (যেমন কার্যকর পরিবর্তন নেই) যাচাই থামিয়ে দেয়।"},"consequence":{"en":"Preview writes nothing to settings or engines. If the world changes afterwards, the preview becomes stale and must be redone.","bn":"প্রিভিউ সেটিং বা ইঞ্জিনে কিছু লেখে না। পরে অবস্থা বদলালে প্রিভিউ পুরোনো হয়ে যায় এবং আবার করতে হয়।"},"data_formula_units":{"en":"Exact decimal arithmetic; every step is shown with units.","bn":"নির্ভুল দশমিক হিসাব; প্রতিটি ধাপ এককসহ দেখানো হয়।"},"linked_report":{"en":"Reports listed in the impact panel; unbuilt ones are marked NOT_BUILT.","bn":"ইমপ্যাক্ট প্যানেলের রিপোর্ট; তৈরি না হলে NOT_BUILT লেখা থাকে।"}}'::jsonb);
INSERT INTO c10_demo.intent_guidance_v1(control_key,module_code,capability_key,content) VALUES('intent.request_box','intent',NULL,'{"title":{"en":"Describe what you want","bn":"আপনি কী চান লিখুন"},"what":{"en":"Write your business rule in Bangla or English. The system matches it to a certified capability or records an engineering requirement.","bn":"বাংলা বা ইংরেজিতে ব্যবসার নিয়ম লিখুন। সিস্টেম এটিকে সার্টিফাইড সক্ষমতার সাথে মেলায় অথবা ইঞ্জিনিয়ারিং রিকোয়ারমেন্ট হিসেবে রাখে।"},"why":{"en":"So you do not need to know menu names or technical settings.","bn":"যাতে মেনু বা টেকনিক্যাল সেটিংয়ের নাম জানতে না হয়।"},"when":{"en":"Whenever you want a threshold, approval limit or margin rule for one business.","bn":"কোনো ব্যবসার সীমা, অনুমোদন-সীমা বা মার্জিন নিয়ম চাইলে।"},"default":{"en":"Nothing is applied. Every request starts as an interpretation you can edit.","bn":"কিছুই প্রয়োগ হয় না। প্রতিটি অনুরোধ আগে সম্পাদনাযোগ্য ব্যাখ্যা হিসেবে শুরু হয়।"},"exception":{"en":"Requests for permissions, code, ledger posting or payments are refused by policy.","bn":"অনুমতি, কোড, লেজার পোস্টিং বা পেমেন্টের অনুরোধ নীতিগতভাবে প্রত্যাখ্যাত।"},"consequence":{"en":"Supported requests can be previewed. Unsupported ones are stored for engineering; they never run.","bn":"সমর্থিত অনুরোধ প্রিভিউ করা যায়। অসমর্থিতগুলো ইঞ্জিনিয়ারিংয়ের জন্য জমা থাকে; চলে না।"},"data_formula_units":{"en":"Parsed with fixed rules (no AI service). Numbers keep their units: %, kg, pcs, litre, currency.","bn":"নির্দিষ্ট নিয়মে পার্স করা হয় (কোনো এআই সার্ভিস নয়)। সংখ্যার একক বজায় থাকে: %, কেজি, পিস, লিটার, মুদ্রা।"},"linked_report":{"en":"History and audit panel below.","bn":"নিচের ইতিহাস ও অডিট প্যানেল।"}}'::jsonb);
INSERT INTO c10_demo.intent_guidance_v1(control_key,module_code,capability_key,content) VALUES('intent.rollback','intent',NULL,'{"title":{"en":"Rollback","bn":"রোলব্যাক"},"what":{"en":"Restores an earlier setting version as a new version; history is never deleted.","bn":"আগের সেটিং সংস্করণটি নতুন সংস্করণ হিসেবে ফেরায়; ইতিহাস মোছা হয় না।"},"why":{"en":"A wrong setting can be undone quickly and traceably.","bn":"ভুল সেটিং দ্রুত ও ট্রেসযোগ্যভাবে ফেরানো যায়।"},"when":{"en":"When the active version behaves badly or was published by mistake.","bn":"সক্রিয় সংস্করণ ঠিক না থাকলে বা ভুলে প্রকাশ হলে।"},"default":{"en":"Only the tenant Owner; you must give a reason.","bn":"শুধু টেন্যান্ট মালিক; কারণ দিতে হবে।"},"exception":{"en":"Fails if someone published a newer version meanwhile (stale).","bn":"ইতিমধ্যে নতুন সংস্করণ প্রকাশ হলে ব্যর্থ হয় (stale)।"},"consequence":{"en":"Creates version N+1 with the old values and an audit event.","bn":"পুরোনো মান নিয়ে N+1 সংস্করণ ও অডিট ইভেন্ট তৈরি হয়।"},"data_formula_units":{"en":"Versions are compared by hash of their parameters.","bn":"সংস্করণ প্যারামিটারের হ্যাশ দিয়ে তুলনা হয়।"},"linked_report":{"en":"History and audit panel.","bn":"ইতিহাস ও অডিট প্যানেল।"}}'::jsonb);
INSERT INTO c10_demo.intent_guidance_v1(control_key,module_code,capability_key,content) VALUES('inventory.low_stock_alert','stock','low_stock_alert','{"title":{"en":"Low stock alert","bn":"কম স্টক সতর্কতা"},"what":{"en":"Flags an item when on-hand quantity is below your number.","bn":"মজুত আপনার সংখ্যার নিচে গেলে আইটেম চিহ্নিত করে।"},"why":{"en":"Avoid stock-outs before they stop sales or production.","bn":"বিক্রি বা উৎপাদন থামার আগেই স্টক-আউট এড়ান।"},"when":{"en":"On stock checks and reorder review.","bn":"স্টক যাচাই ও রিঅর্ডার পর্যালোচনায়।"},"default":{"en":"Warn.","bn":"সতর্কতা।"},"exception":{"en":"Negative thresholds are invalid.","bn":"ঋণাত্মক সীমা অবৈধ।"},"consequence":{"en":"Stored through the A045 engine registry; advisory only, no purchase is created.","bn":"A045 ইঞ্জিন রেজিস্ট্রির মাধ্যমে সংরক্ষিত; শুধু পরামর্শ, ক্রয় তৈরি হয় না।"},"data_formula_units":{"en":"matched when on_hand < threshold, in the item''s stock unit.","bn":"মজুত < সীমা হলে মেলে, আইটেমের স্টক এককে।"},"linked_report":{"en":"Stock position (read-only, existing).","bn":"স্টক পজিশন (শুধু পড়া, বিদ্যমান)।"}}'::jsonb);
INSERT INTO c10_demo.intent_guidance_v1(control_key,module_code,capability_key,content) VALUES('inventory.wastage_threshold','production','wastage_threshold','{"title":{"en":"Wastage threshold","bn":"অপচয় সীমা"},"what":{"en":"Warns when wasted quantity is a larger share of produced quantity than your limit.","bn":"নষ্ট পরিমাণ উৎপাদিত পরিমাণের তুলনায় আপনার সীমার বেশি হলে সতর্ক করে।"},"why":{"en":"Sweets and bakery lose margin quietly through spoilage.","bn":"মিষ্টি ও বেকারিতে নষ্ট হয়ে নীরবে লাভ কমে।"},"when":{"en":"Per batch, when production is recorded.","bn":"প্রতি ব্যাচে, উৎপাদন লেখার সময়।"},"default":{"en":"Outcome is a warning; unit is kg unless you state another.","bn":"ফলাফল সতর্কতা; অন্য একক না বললে কেজি।"},"exception":{"en":"Wasted quantity above produced quantity is invalid input.","bn":"উৎপাদিতের বেশি নষ্ট পরিমাণ অবৈধ ইনপুট।"},"consequence":{"en":"Advisory only. No stock movement or cost is posted.","bn":"শুধু পরামর্শ। কোনো স্টক মুভমেন্ট বা খরচ পোস্ট হয় না।"},"data_formula_units":{"en":"wastage % = wasted ÷ produced × 100. Both quantities in the same unit.","bn":"অপচয় % = নষ্ট ÷ উৎপাদিত × ১০০। দুটি পরিমাণ একই এককে।"},"linked_report":{"en":"Wastage report: NOT_BUILT (engineering requirement).","bn":"অপচয় রিপোর্ট: NOT_BUILT (ইঞ্জিনিয়ারিং রিকোয়ারমেন্ট)।"}}'::jsonb);
INSERT INTO c10_demo.intent_guidance_v1(control_key,module_code,capability_key,content) VALUES('pricing.margin_floor_approval','costing','margin_floor_approval','{"title":{"en":"Margin floor approval","bn":"ন্যূনতম মার্জিনে অনুমোদন"},"what":{"en":"Marks a sale or order as needing approval when margin is under your floor.","bn":"মার্জিন সীমার নিচে গেলে বিক্রি বা অর্ডারে অনুমোদন দরকার বলে চিহ্নিত করে।"},"why":{"en":"Stops unnoticed loss-making deals.","bn":"অজান্তে লোকসানের চুক্তি আটকায়।"},"when":{"en":"At quotation or order entry.","bn":"কোটেশন বা অর্ডার এন্ট্রির সময়।"},"default":{"en":"Approval required (advisory flag).","bn":"অনুমোদন প্রয়োজন (পরামর্শমূলক ফ্ল্যাগ)।"},"exception":{"en":"Floor must be between 0 and 99.99 %.","bn":"সীমা ০ থেকে ৯৯.৯৯ % এর মধ্যে হতে হবে।"},"consequence":{"en":"The approval is not enforced yet; the flag is stored via A045.","bn":"অনুমোদন এখনো বাধ্যতামূলক নয়; ফ্ল্যাগ A045-এর মাধ্যমে সংরক্ষিত।"},"data_formula_units":{"en":"matched when margin % < threshold %.","bn":"মার্জিন % < সীমা % হলে মেলে।"},"linked_report":{"en":"Margin report: NOT_BUILT.","bn":"মার্জিন রিপোর্ট: NOT_BUILT।"}}'::jsonb);
INSERT INTO c10_demo.intent_guidance_v1(control_key,module_code,capability_key,content) VALUES('pricing.pack_discount_margin','costing','pack_discount_margin','{"title":{"en":"Pack discount margin","bn":"প্যাক ডিসকাউন্ট মার্জিন"},"what":{"en":"Checks the margin of a pack after discount and shows the largest discount that keeps your margin floor.","bn":"ছাড়ের পর প্যাকের মার্জিন যাচাই করে এবং মার্জিন সীমা ধরে রাখার সর্বোচ্চ ছাড় দেখায়।"},"why":{"en":"Paint and hardware packs of different litres need exact unit costs.","bn":"পেইন্ট ও হার্ডওয়্যারের বিভিন্ন লিটারের প্যাকে নির্ভুল একক খরচ দরকার।"},"when":{"en":"When setting discounts or price lists.","bn":"ছাড় বা মূল্যতালিকা ঠিক করার সময়।"},"default":{"en":"Warn when margin falls below the floor; currency BDT unless stated.","bn":"মার্জিন সীমার নিচে গেলে সতর্ক; উল্লেখ না থাকলে মুদ্রা BDT।"},"exception":{"en":"Discount of 100% or zero price is invalid.","bn":"১০০% ছাড় বা শূন্য দাম অবৈধ।"},"consequence":{"en":"Advisory only. No price or discount is changed.","bn":"শুধু পরামর্শ। কোনো দাম বা ছাড় বদলায় না।"},"data_formula_units":{"en":"net = price × (1 − d/100); cost = cost per litre × litres; margin = (net − cost) ÷ net × 100.","bn":"নিট = দাম × (১ − ছাড়/১০০); খরচ = লিটার-প্রতি খরচ × লিটার; মার্জিন = (নিট − খরচ) ÷ নিট × ১০০।"},"linked_report":{"en":"Margin report: NOT_BUILT.","bn":"মার্জিন রিপোর্ট: NOT_BUILT।"}}'::jsonb);
INSERT INTO c10_demo.intent_guidance_v1(control_key,module_code,capability_key,content) VALUES('purchase.order_total_approval','purchase','order_total_approval','{"title":{"en":"Large order approval","bn":"বড় অর্ডারে অনুমোদন"},"what":{"en":"Flags purchase or project-materials orders at or above your amount for Owner approval.","bn":"আপনার অঙ্ক বা তার বেশি ক্রয়/প্রকল্প-মালামাল অর্ডার মালিকের অনুমোদনের জন্য চিহ্নিত করে।"},"why":{"en":"Construction and project buying should not exceed limits unseen.","bn":"নির্মাণ ও প্রকল্পের ক্রয় অজান্তে সীমা ছাড়াবে না।"},"when":{"en":"When an order is drafted.","bn":"অর্ডারের খসড়া তৈরির সময়।"},"default":{"en":"Approval required (advisory flag); currency BDT unless stated.","bn":"অনুমোদন প্রয়োজন (পরামর্শমূলক ফ্ল্যাগ); উল্লেখ না থাকলে মুদ্রা BDT।"},"exception":{"en":"Zero or negative limits are invalid.","bn":"শূন্য বা ঋণাত্মক সীমা অবৈধ।"},"consequence":{"en":"Nothing is posted or approved automatically. The read-only materials report is not built.","bn":"কিছু স্বয়ংক্রিয়ভাবে পোস্ট বা অনুমোদিত হয় না। শুধু-পড়া মালামাল রিপোর্ট তৈরি হয়নি।"},"data_formula_units":{"en":"matched when order total ≥ limit, in the stated currency.","bn":"অর্ডার মোট ≥ সীমা হলে মেলে, উল্লিখিত মুদ্রায়।"},"linked_report":{"en":"Project materials report: NOT_BUILT.","bn":"প্রকল্প মালামাল রিপোর্ট: NOT_BUILT।"}}'::jsonb);
